require("./conf.d/init/*.lua")

local function require_optional(pattern)
    local ok, err = pcall(require, pattern)
    if not ok and not tostring(err):find("wildcard found no") then
        error(err)
    end
end

require_optional("./custom.d/init/*.lua")
require("./conf.d/regular/*.lua")
require_optional("./custom.d/regular/*.lua")
